package com.donutsmp.gamehub.money;
import java.util.Locale;
public final class AmountParser {private AmountParser(){}public record ParseResult(boolean ok,long value,String error){static ParseResult ok(long v){return new ParseResult(true,v,null);}static ParseResult fail(String e){return new ParseResult(false,0L,e);}}
 public static ParseResult parse(String input){if(input==null)return ParseResult.fail("Enter an amount");String s=input.trim().toLowerCase(Locale.ROOT).replace(",","").replace("_","");if(s.startsWith("$"))s=s.substring(1);if(s.isEmpty())return ParseResult.fail("Enter an amount");int exp=0;char last=s.charAt(s.length()-1);switch(last){case'k'->exp=3;case'm'->exp=6;case'b'->exp=9;case't'->exp=12;default->{}}if(exp!=0)s=s.substring(0,s.length()-1);if(s.isEmpty())return ParseResult.fail("Invalid amount");String intPart=s,frac="";int dot=s.indexOf('.');if(dot>=0){intPart=s.substring(0,dot);frac=s.substring(dot+1);}if(intPart.isEmpty()||!allDigits(intPart)||(dot>=0&&(frac.isEmpty()||!allDigits(frac))))return ParseResult.fail("Invalid amount");int end=frac.length();while(end>0&&frac.charAt(end-1)=='0')end--;frac=frac.substring(0,end);if(frac.length()>exp)return ParseResult.fail("Too many decimal places");long whole;try{whole=Long.parseLong(intPart);}catch(NumberFormatException e){return ParseResult.fail("Amount too large");}try{long value=Math.multiplyExact(whole,pow10(exp));if(!frac.isEmpty()){long fracVal=Long.parseLong(frac);value=Math.addExact(value,fracVal*pow10(exp-frac.length()));}if(value<=0)return ParseResult.fail("Amount must be greater than zero");return ParseResult.ok(value);}catch(ArithmeticException e){return ParseResult.fail("Amount too large");}}
 private static boolean allDigits(String s){for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c<'0'||c>'9')return false;}return true;}private static long pow10(int n){long r=1L;for(int i=0;i<n;i++)r*=10L;return r;}
}
